# Terminal palette for the login shell. Source this file from the shell's own
# startup file; it exports LS_COLORS and touches nothing else.

LS_COLORS="di={{accent}}:ln={{accent-cyan}}:pi={{accent-violet}}:so={{success}}:bd={{warning}}:cd={{warning}}:or={{ink-faint-solid}}:ex={{success}}:do={{accent-violet}}:su={{error}}:sg={{error}}:tw={{accent-soft}}:ow={{accent-soft}}:st={{accent-soft}}:mi={{error}}:rs={{ink}}:fi={{ink}}:*.md={{ink-secondary}}:*.json={{warning}}:*.toml={{warning}}:*.yaml={{warning}}:*.yml={{warning}}:*.css={{accent-cyan}}:*.ts={{accent}}:*.tsx={{accent}}:*.js={{warning}}:*.sh={{success}}:*.lock={{ink-faint-solid}}"
export LS_COLORS
